const crypto = require('crypto');

const item = $input.first().json;
const appID = String(item.AppID);
const secret = String(item.Secret);
const timestamp = String(item.formattedDate);
const payloadStr = String(item.PayloadStr);

// Shopee Affiliate BR: SHA256(AppID + Secret + Timestamp + Payload)
// Based on official header name 'SHA256' (not HMAC)
const message = appID + secret + timestamp + payloadStr;
const signature = crypto
  .createHash('sha256')
  .update(message, 'utf8')
  .digest('hex');

return [{ json: { ...item, data: signature } }];

// Filtrar Comissão (usa variáveis do node "Configuração do fluxo")

const cfg = $node["Configuração do fluxo"].json;

// seus nomes exatos (mantendo o tipo "Comission")
const minComission = Number(cfg.minComission ?? 1); // ex: 1.00 (R$)
const minComissionRate = Number(cfg.minComissionRate ?? 0); // ex: 0.30 (30%)

const items = $input.all();

return items.filter((it) => {
  const o = it.json.oferta || it.json;

  const commission = Number(o.commission ?? 0);
  const commissionRate = Number(o.commissionRate ?? 0);

  return commission >= minComission && commissionRate >= minComissionRate;
});

// ============================================
// Filtrar Achadinhos (Preço + Palavras) - Shopee
// ============================================

// ========================
// 1) CONFIG (puxa do node "Configuração do fluxo")
// ========================

// jeito mais compatível com Code node:
const cfgItem = ($items("Configuração do fluxo")?.[0]?.json) ?? {};
const maxPrice = Number(cfgItem.maxPrice ?? 79.90);
const minPrice = Number(cfgItem.minPrice ?? 0);   // ✅ NOVO
const minScore = Number(cfgItem.minScore ?? 1);   // opcional

// ========================
// 2) KEYWORDS (edite à vontade)
// ========================
const POSITIVE_KEYWORDS = [
  "kit", "organizador", "suporte", "capa", "capinha", "pelicula", "película",
  "usb", "type c", "tipo c", "carregador", "cabo", "adaptador",

  "led", "luz", "lanterna", "sensor", "magnetico", "magnético", "ima", "imã",
  "portatil", "portátil", "dobravel", "dobrável", "recarregavel", "recarregável", "silicone",

  "cozinha", "casa", "decoracao", "decoração", "banheiro", "limpeza",

  "pet", "gato", "cachorro", "automotivo", "carro",

  // utilidades / organização
  "porta", "gancho", "ganchos", "cabide", "cabideiro", "prateleira",
  "caixa", "caixinha", "pote", "pote hermetico", "pote hermético", "recipiente",
  "cesto", "lixeira", "dispenser", "dispensador", "dosador", "borrifador", "pulverizador",
  "escova", "esponja", "toalha", "pano", "tapete", "capacho",

  // tech / celular
  "pelicula 3d", "película 3d", "suporte celular", "suporte carro", "fone", "fone bluetooth",

  // decoração
  "decorativo", "decorativa", "quadro", "placa", "plaquinha",

  // beleza / cuidados pessoais  --> [PREENCHIDO: faltava no meio do arquivo]
  "maquiagem", "batom", "base", "skincare", "hidratante", "esmalte", "perfume", "necessaire",

  // bebê / infantil  --> [PREENCHIDO]
  "bebe", "bebê", "infantil", "mordedor", "chupeta", "brinquedo",

  // moda (roupas e acessórios)
  "camiseta", "camisa", "blusa", "cropped", "moletom", "jaqueta",
  "calca", "calça", "bermuda", "short", "vestido", "saia", "conjunto",
  "moda", "feminina", "masculino", "unissex", "casual", "basico", "básico", "inverno", "verao", "verão"
];

const NEGATIVE_KEYWORDS = [
  "emagrecedor", "capsulas", "cápsulas", "gotas", "original envio hoje", "green", "lepti",
  "curso", "ebook", "apostila", "assinatura",
  "casamento", "gravata", "urna", "pix", "alianca", "aliança", "porta alianca", "porta aliança"
];

// ========================
// 3) HELPERS
// ========================
function toNumber(v) {
  if (v === null || v === undefined) return NaN;
  if (typeof v === "number") return v;
  const s = String(v).replace(/\./g, "").replace(",", ".").replace(/[^\d.-]/g, "");
  const n = parseFloat(s);
  return isNaN(n) ? NaN : n;
}

function normalize(str) {
  return String(str || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, ""); // remove acentos
}

function countHits(normalizedText, keywords) {
  const hits = [];
  for (const kw of keywords) {
    if (normalizedText.includes(normalize(kw))) hits.push(kw);
  }
  return hits;
}

// ========================
// 4) COLETA DOS ITENS (vem do HTTP Request1)
// ========================
// Estrutura da API da Shopee: data.productOfferV2.nodes[]
const httpItem = $input.first().json;
const nodes = httpItem?.data?.productOfferV2?.nodes ?? [];

// ========================
// 5) FILTRO DE PREÇO + PALAVRAS + SCORE
// ========================
const results = [];

for (const node of nodes) {
  const productName = node.productName ?? "";
  const price = toNumber(node.price);
  const commissionRate = toNumber(node.commissionRate);
  const commission = toNumber(node.commission);
  const offerLink = node.offerLink ?? "";
  const productLink = node.productLink ?? "";
  const imageUrl = node.imageUrl ?? "";

  // filtro de preço
  if (isNaN(price) || price < minPrice || price > maxPrice) continue;

  const normalizedName = normalize(productName);
  const posHits = countHits(normalizedName, POSITIVE_KEYWORDS);
  const negHits = countHits(normalizedName, NEGATIVE_KEYWORDS);

  // descarta na hora se bater em palavra negativa (curso, emagrecedor, etc)
  if (negHits.length > 0) continue;

  const score = posHits.length;

  // filtro de score mínimo (quantas palavras-chave positivas bateram)
  if (score < minScore) continue;

  results.push({
    json: {
      oferta: {
        productName,
        offerLink,
        productLink,
        imageUrl,
        price,
        commissionRate,
        commission,
        score,
        posHits,
        negHits
      }
    }
  });
}

// ========================
// 6) ORDENA (maior score primeiro, depois maior comissão)
// ========================
results.sort((a, b) => {
  const s = b.json.oferta.score - a.json.oferta.score;
  if (s !== 0) return s;
  return b.json.oferta.commission - a.json.oferta.commission;
});

return results;

// Node: Diversificar (dedupe + limite por categoria)
// Entrada esperada: [{ oferta: {...} }, { oferta: {...} }, ...]

const MAX_PER_CATEGORY = 3;

// Só aplicamos limite pesado nessas categorias (as que costumam "inundar" o feed)
const LIMITED_CATEGORIES = new Set([
  "roupas",
  "oculos",
  "relogio",
  "livros",
  "capinhas",
  "peliculas",
]);

// Palavras-chave para inferir a categoria a partir do productName
const CATEGORY_RULES = [
  {
    cat: "roupas",
    keys: [
      "camiseta","camisa","blusa","cropped","moletom","jaqueta",
      "calca","calça","bermuda","short","vestido","saia","conjunto",
      "moda","feminino","masculino","unissex","casual","basico","básico","inverno","verao","verão"
    ],
  },
  {
    cat: "oculos",
    keys: ["oculos","óculos","lente","uv400","solar","armação","armacao"],
  },
  {
    cat: "relogio",
    keys: ["relogio","relógio","smartwatch","pulseira","cronometro"],
  },
  {
    cat: "livros",
    keys: ["livro","livros","literatura","romance","dicionario"],
  },
  {
    cat: "capinhas",
    keys: ["capinha","capinhas","capa celular","case","case iphone","case samsung"],
  },
  {
    cat: "peliculas",
    keys: ["pelicula","película","vidro","glass","protector","protetor de tela"],
  },
];

function norm(s) {
  return String(s || "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // remove acentos
    .replace(/[^\p{L}\p{N}\s]+/gu, " ")                // tira pontuação
    .replace(/\s+/g, " ")
    .trim();
}

function detectCategory(productName) {
  const n = norm(productName);
  for (const rule of CATEGORY_RULES) {
    for (const k of rule.keys) {
      if (n.includes(norm(k))) return rule.cat;
    }
  }
  return "outros";
}

// --- começa aqui ---
const itemsIn = $input.all();

// (opcional) se quiser priorizar os melhores antes de cortar repetidos,
// ordena por score (desc) e depois por comissão (desc)
itemsIn.sort((a, b) => {
  const A = a.json?.oferta || {};
  const B = b.json?.oferta || {};
  const sA = Number(A.score ?? 0);
  const sB = Number(B.score ?? 0);
  if (sB !== sA) return sB - sA;

  const cA = Number(A.commission ?? 0);
  const cB = Number(B.commission ?? 0);
  return cB - cA;
});

// --- estruturas de controle ---
const out = [];
const seenNames = new Set();
const catCounts = new Map();

for (const it of itemsIn) {
  const oferta = it.json?.oferta || it.json || {};
  const nameKey = norm(oferta.productName);

  // 1) nenhum item igual
  if (seenNames.has(nameKey)) continue;

  const cat = detectCategory(oferta.productName);
  oferta._categoria = cat; // útil para debug / próximos filtros

  // 2) no máximo 3 para categorias repetitivas
  if (LIMITED_CATEGORIES.has(cat)) {
    const current = catCounts.get(cat) ?? 0;
    if (current >= MAX_PER_CATEGORY) continue;
    catCounts.set(cat, current + 1);
  }

  seenNames.add(nameKey);
  out.push({ json: { oferta } });
}

return out;

