// n8n Code Node (JavaScript)
// Limpa output vindo com ```json ... ``` e transforma em JSON de verdade (quando possível).

function stripMarkdownFences(text) {
  if (typeof text !== "string") return text;

  // Remove ```json, ``` e variantes
  // Ex: ```json\n{...}\n```  ->  {...}
  return text
    .trim()
    .replace(/^```[a-zA-Z0-9_-]*\s*\n?/, "") // abre fence
    .replace(/\n?```$/, "")                   // fecha fence
    .trim();
}

return $input.all().map((item) => {
  const raw = item.json?.output;

  if (raw == null) {
    return { json: { ...item.json, cleanedText: "", parsed: null } };
  }

  const cleanedText = stripMarkdownFences(String(raw));

  // Tenta parsear como JSON
  let parsed = null;
  try {
    parsed = JSON.parse(cleanedText);
  } catch (e) {
    // Se falhar, tenta um "resgate" comum: remover BOM / chars estranhos
    try {
      const rescued = cleanedText.replace(/^\uFEFF/, "").trim();
      parsed = JSON.parse(rescued);
    } catch (e2) {
      parsed = null;
    }
  }

  // Se conseguiu parsear e tem "copy", já sobe um campo copy direto
  const copy = parsed && typeof parsed === "object" && parsed.copy ? parsed.copy : null;

  return {
    json: {
      ...item.json,
      cleanedText, // string sem ``` ```
      parsed,      // objeto (ou null)
      copy         // atalho (ou null)
    }
  };
});
